'use strict';
const movies=[
{id:0,title:'Sau màn đêm',genre:'Kinh dị',duration:118,age:'T18',director:'Nguyễn Minh An',cast:'Khánh Linh, Hoàng Nam, Tuấn Phong',desc:'Khi sự thật dần lộ diện trong bóng tối, ba người bạn phải đối mặt với những bí mật bị chôn vùi giữa thành phố mưa. Một đêm duy nhất sẽ thay đổi tất cả.',status:'now'},
{id:1,title:'Tử chiến trên không',genre:'Hành động',duration:125,age:'T16',director:'Trần Hải Long',cast:'Minh Quân, Bảo Anh',desc:'Một chuyến bay mất liên lạc. Một nhiệm vụ không có đường lui. Phi công trẻ phải đưa ra quyết định giữa bầu trời và bảo vệ những người anh yêu thương.',status:'now'},
{id:2,title:'Dế Mèn: Cuộc phiêu lưu tới xóm lầy lội',genre:'Hoạt hình',duration:96,age:'P',director:'Lê Thanh',cast:'Lồng tiếng: Hà My, Quốc Bảo',desc:'Cùng Dế Mèn và những người bạn khám phá thế giới rộng lớn, vượt qua thử thách và học cách trân trọng tình bạn trong cuộc phiêu lưu dành cho cả gia đình.',status:'now'},
{id:3,title:'Bóng đè',genre:'Kinh dị',duration:104,age:'T18',director:'Vũ Anh',cast:'Ngọc Anh, Minh Tú',desc:'Căn nhà ven hồ tưởng chừng yên bình lại che giấu một bí mật. Mỗi giấc ngủ đưa cô gái đến gần hơn với sự thật mà cô không muốn nhớ.',status:'now'},
{id:4,title:'Mưa trên thành phố',genre:'Tâm lý',duration:112,age:'T13',director:'Phạm Nhật',cast:'Thanh Trúc, Anh Khoa',desc:'Hai con người xa lạ gặp nhau trong những ngày mưa. Giữa thành phố vội vã, họ tìm thấy một lý do để dừng lại và lắng nghe trái tim mình.',status:'now'},
{id:5,title:'Vòng tay nắng',genre:'Tâm lý',duration:120,age:'T13',desc:'Hành trình trở về của những người trẻ, nơi gia đình và ký ức đan xen để tạo nên một khởi đầu mới.',status:'soon',release:'06/11/2026'},
{id:6,title:'Thám tử và bí ẩn cuối cùng',genre:'Hoạt hình',duration:108,age:'P',desc:'Một câu đố mới, những dấu vết bất ngờ và cuộc chạy đua với thời gian của nhóm thám tử trẻ.',status:'soon',release:'13/11/2026'},
{id:7,title:'Phi vụ cuối cùng',genre:'Hành động',duration:124,age:'T16',desc:'Một nhóm cộng sự tái hợp cho phi vụ cuối cùng, nhưng không ai biết ai đang giữ bí mật.',status:'soon',release:'20/11/2026'},
{id:8,title:'Elio',genre:'Hoạt hình',duration:99,age:'P',desc:'Một chuyến phiêu lưu ngoài vũ trụ và câu chuyện về lòng dũng cảm, sự khác biệt cùng tình bạn.',status:'soon',release:'27/11/2026'},
{id:9,title:'Dưới đáy hồ',genre:'Kinh dị',duration:105,age:'T18',desc:'Một hồ nước cất giữ những ký ức chưa được kể. Khi mặt hồ tĩnh lặng, những bí ẩn bắt đầu thức giấc.',status:'soon',release:'04/12/2026'}];
const cinemas=[{id:0,name:'YeuMinhEm Cinema Đồng Khởi',address:'Khu vực Đồng Khởi, Quận 1, TP. Hồ Chí Minh',city:'TP. Hồ Chí Minh'},{id:1,name:'YeuMinhEm Cinema Thủ Đức',address:'Khu vực Võ Văn Ngân, TP. Thủ Đức, TP. Hồ Chí Minh',city:'TP. Hồ Chí Minh'},{id:2,name:'YeuMinhEm Cinema Tây Hồ',address:'Khu vực Võ Chí Công, Tây Hồ, Hà Nội',city:'Hà Nội'}];
const slots=['09:30','12:15','15:00','18:30','21:15'];
const $=s=>document.querySelector(s),app=$('#app');
const read=(k,f)=>{try{return JSON.parse(localStorage.getItem(k))??f}catch{return f}};
let users=read('cc_users',[]),orders=read('cc_orders',[]),session=read('cc_session',null),booking=readBooking(),slide=0,slideTimer=null,filterGenre='Tất cả',movieStatus='now',loginNext=null;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>new Intl.NumberFormat('vi-VN',{style:'currency',currency:'VND'}).format(n);
const uid=()=>globalThis.crypto?.randomUUID?.()||Date.now().toString(36)+Math.random().toString(36).slice(2);
function readBooking(){try{return JSON.parse(sessionStorage.getItem('cc_booking'))||null}catch{return null}}
function persistBooking(){try{if(booking)sessionStorage.setItem('cc_booking',JSON.stringify(booking));else sessionStorage.removeItem('cc_booking')}catch{}}
const store=()=>{localStorage.setItem('cc_users',JSON.stringify(users));localStorage.setItem('cc_orders',JSON.stringify(orders));localStorage.setItem('cc_session',JSON.stringify(session));persistBooking()};
function toggleMenu(){const open=document.querySelector('nav').classList.toggle('open');document.querySelector('[aria-controls="mainNav"]').setAttribute('aria-expanded',String(open))}
function closeMenu(){document.querySelector('nav').classList.remove('open');document.querySelector('[aria-controls="mainNav"]').setAttribute('aria-expanded','false')}
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeMenu()});

function toast(s){$('#toast').textContent=s;$('#toast').classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3500)}
function showModal(html){$('#modalBody').innerHTML=html;if(!$('#modal').open)$('#modal').showModal()}
function closeModal(){$('#modal').close()}
$('#modal').addEventListener('click',e=>{if(e.target===$('#modal'))closeModal()});
function info(title,text){showModal(`<h2>${esc(title)}</h2><p class="sub">${esc(text)}</p><button class="primary" onclick="closeModal()">Đã hiểu</button>`)}
function user(){return users.find(u=>u.id===session)}
function updateAccount(){$('#accountBtn').textContent=user()?user().email==='guest@cinema.example'?'Khách demo':user().name.split(' ').slice(-1)[0]:'Đăng nhập'}
function dateKey(offset=0){const d=new Date();d.setDate(d.getDate()+offset);return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}
function fmtDate(key){return new Date(key+'T12:00:00').toLocaleDateString('vi-VN')}
function dayOptions(){return Array.from({length:7},(_,i)=>`<option value="${dateKey(i)}">${i===0?'Hôm nay · ':''}${fmtDate(dateKey(i))}</option>`).join('')}
function validSlot(date,time){return new Date(date+'T'+time+':00').getTime()>Date.now()}
function mCard(m){return `<article class="card"><button class="poster-button" onclick="location.hash='movie/${m.id}'" aria-label="Chi tiết ${esc(m.title)}"><img class="poster" src="assets/poster${m.id}.webp" alt="${esc(m.title)}" loading="lazy"></button><div class="card-body"><h3>${esc(m.title.toUpperCase())}</h3><div class="meta">${m.status==='now'?`${m.duration} phút <span class="age">${m.age}</span>`:`Khởi chiếu ${m.release}`}</div><button class="${m.status==='now'?'primary':'outline'}" onclick="location.hash='movie/${m.id}${m.status==='now'?'?book=1':''}'">${m.status==='now'?'Đặt vé ngay':'Xem chi tiết'} →</button></div></article>`}
function home(){app.innerHTML=`<section class="cinema-intro" aria-label="Giới thiệu YeuMinhEm Cinema"><div class="intro-art"></div><div class="intro-copy"><div class="eyebrow">CHÀO MỪNG ĐẾN VỚI</div><h1>YeuMinhEm<br><span>Cinema.</span></h1><h2>Nơi những câu chuyện<br>trở thành cảm xúc.</h2><p>Một cuộc hẹn cùng bạn bè, một buổi tối dành cho người thương, hay một khoảng thời gian cho chính mình. Khám phá thế giới điện ảnh và chọn chỗ ngồi cho câu chuyện tiếp theo của bạn.</p><div class="actions"><a href="#cinemas" class="primary">Khám phá rạp ↗</a><button class="outline" onclick="document.getElementById('hotMovies').scrollIntoView({behavior:'smooth'})">Xem phim đang chiếu ↓</button></div><div class="intro-features"><span>01 <b>Khám phá phim</b></span><span>02 <b>Chọn ghế yêu thích</b></span><span>03 <b>Đặt vé dễ dàng</b></span></div></div><button class="intro-scroll" onclick="document.getElementById('hotMovies').scrollIntoView({behavior:'smooth'})" aria-label="Cuộn xuống Phim hot">KHÁM PHÁ THÊM <span>↓</span></button><div class="intro-signature">CHẠM VÀO ĐIỆN ẢNH<br><b>YeuMinhEm Cinema</b></div></section><div class="hot-slider-wrap" id="hotMovies"><div class="hot-slider-heading"><div><div class="eyebrow">ĐỪNG BỎ LỠ TRÊN MÀN ẢNH</div><h2>Phim hot hôm nay</h2></div><a href="#movies">Tất cả phim ↗</a></div><section class="hero" id="hero" aria-label="Slide Phim hot"></section></div><div class="container"><div class="quickbar"><strong>ĐẶT VÉ NHANH<small class="sub" style="display:block;font-size:10px;margin-top:8px">Chọn suất chiếu dành cho bạn</small></strong><label>Rạp chiếu<select id="quickCinema">${cinemas.map(c=>`<option value="${c.id}">${c.name}</option>`).join('')}</select></label><label>Phim<select id="quickMovie">${movies.filter(m=>m.status==='now').map(m=>`<option value="${m.id}">${m.title}</option>`).join('')}</select></label><label>Ngày xem<select id="quickDate">${dayOptions()}</select></label><button class="primary" onclick="location.hash='schedule?movie='+$('#quickMovie').value+'&cinema='+$('#quickCinema').value+'&date='+$('#quickDate').value">Tìm suất chiếu →</button></div><div class="movie-discovery"><div class="movie-feed"><section class="feed-panel"><div class="feed-toolbar"><div><div class="eyebrow">KHÁM PHÁ</div><h2>Thế giới điện ảnh</h2></div><select id="feedStatus" aria-label="Trạng thái phim" onchange="renderFeed()"><option value="now">Đang chiếu</option><option value="soon">Sắp chiếu</option><option value="all">Tất cả phim</option></select></div><div class="feed-filters"><div class="chips" id="homeGenres">${genreChips('homeFilter')}</div><span id="feedCount"></span></div><div class="mini-movie-grid" id="homeGrid">${movies.filter(m=>m.status==='now').map(miniMovieCard).join('')}</div><a class="feed-more" href="#movies">Khám phá tất cả phim ↗</a></section><section class="soon-shelf"><div class="section-head"><div><div class="eyebrow">SẮP RA MẮT</div><h2>Đón chờ trên màn ảnh</h2></div><a href="#movies?status=soon">Xem tất cả ↗</a></div><div class="mini-movie-grid">${movies.filter(m=>m.status==='soon').slice(0,3).map(miniMovieCard).join('')}</div></section></div><aside class="movie-side"><section class="side-panel"><div class="side-heading"><h3>Phim nổi bật</h3><span>ĐỀ CỬ</span></div><p class="side-sub">Lựa chọn từ YeuMinhEm Cinema</p>${[0,1,4].map((id,i)=>`<a class="ranked-movie" href="#movie/${id}"><span class="rank-number">0${i+1}</span><img src="assets/poster${id}.webp" alt=""><div><strong>${esc(movies[id].title)}</strong><small>${movies[id].genre} · ${movies[id].duration} phút</small></div><span class="rank-arrow">↗</span></a>`).join('')}</section><section class="side-panel"><div class="side-heading"><h3>Khám phá thể loại</h3><span>04</span></div>${['Hành động','Tâm lý','Hoạt hình','Kinh dị'].map((g,i)=>`<button class="genre-row" onclick="homeFilter('${g}');document.querySelector('.feed-panel').scrollIntoView({behavior:'smooth',block:'start'})"><span>${['↗','♡','✧','◈'][i]} ${g}</span><small>${movies.filter(m=>m.genre===g).length} phim →</small></button>`).join('')}</section><section class="side-panel side-invite"><div class="eyebrow">YeuMinhEm CINEMA</div><h3>Một chỗ ngồi.<br>Ngàn cảm xúc.</h3><p>Chọn suất chiếu phù hợp và hẹn nhau tại rạp.</p><a class="primary" href="#schedule">Tìm lịch chiếu ↗</a></section></aside></div></div>`;renderFeed();heroRender();if(!matchMedia('(prefers-reduced-motion: reduce)').matches)slideTimer=setInterval(()=>{if(!$('#modal').open&&!document.hidden)setSlide(slide+1)},6500);$('#hero').addEventListener('mouseenter',()=>clearInterval(slideTimer));$('#hero').addEventListener('mouseleave',()=>{if(!matchMedia('(prefers-reduced-motion: reduce)').matches){clearInterval(slideTimer);slideTimer=setInterval(()=>{if(!$('#modal').open&&!document.hidden)setSlide(slide+1)},6500)}})}
function heroRender(){
 const m=movies[[0,1,4][slide]],el=$('#hero');if(!el)return;const intro=false;
 el.style.setProperty('--hero',`url('assets/${m.id===0?'hero.webp':`poster${m.id}.webp`}')`);
 el.classList.toggle('intro-slide',intro);
 el.innerHTML=`<div class="hero-vertical"><span>YeuMinhEm</span><i></i><span>CINEMA</span></div><div class="hero-copy"><div class="eyebrow">${intro?'CẢM XÚC THẬT. TRẢI NGHIỆM MỚI.':'PHIM HOT · ĐANG CHIẾU'}</div><h2>${intro?'ĐIỆN ẢNH<br>KHÔNG GIỚI HẠN':esc(m.title.toUpperCase())}</h2>${intro?'<p class="hero-intro-line">Mở cánh cửa đến những thế giới chưa từng biết.</p>':`<p>${esc(m.desc.slice(0,120))}…</p><div class="meta">${m.genre} · ${m.duration} phút <span class="age">${m.age}</span></div>`}<div class="actions">${intro?'<a class="primary hero-explore" href="#movies">Khám phá phim ↗</a>':`<a class="primary hero-explore" href="#movie/${m.id}?book=1">Đặt vé ngay ↗</a>`}</div></div><div class="hero-side-index">${[0,1,2].map(i=>`<button class="${slide===i?'active':''}" aria-label="Slide ${i+1}" aria-pressed="${slide===i}" onclick="setSlide(${i})">0${i+1}</button>`).join('')}</div><div class="hero-bottom"><button class="hero-play" onclick="${intro?'openFeaturedTrailer()':`trailer(${m.id})`}" aria-label="Xem trailer phim nổi bật">▷</button><span class="hero-signature">YeuMinhEm <b>CINEMA.</b><small>CHẠM VÀO ĐIỆN ẢNH</small></span><div class="hero-pagination"><span><b>0${slide+1}</b> / 03</span><button aria-label="Phim hot trước" onclick="setSlide(slide-1)">‹</button><button aria-label="Phim hot tiếp theo" onclick="setSlide(slide+1)">›</button></div></div>`;
}
function openFeaturedTrailer(){trailer(0)}
function setSlide(i){slide=(i+3)%3;heroRender()}
function genreChips(fn){return ['Tất cả','Hành động','Tâm lý','Hoạt hình','Kinh dị'].map(g=>`<button class="chip ${g===filterGenre?'active':''}" onclick="${fn}('${g}')">${g}</button>`).join('')}
function miniMovieCard(m){return `<article class="mini-movie-card"><button class="mini-art" onclick="location.hash='movie/${m.id}'" aria-label="Chi tiết ${esc(m.title)}"><img src="assets/poster${m.id}.webp" alt="${esc(m.title)}" loading="lazy"><span class="mini-badge">${m.status==='now'?'ĐANG CHIẾU':'SẮP CHIẾU'}</span><span class="mini-open">↗</span></button><div class="mini-content"><div class="mini-title-row"><h3>${esc(m.title)}</h3><span class="age">${m.age}</span></div><div class="mini-info"><div><small>Thể loại</small><strong>${m.genre}</strong></div><div><small>${m.status==='now'?'Thời lượng':'Khởi chiếu'}</small><strong>${m.status==='now'?m.duration+' phút':m.release}</strong></div></div><div class="mini-actions">${m.status==='now'?`<a class="primary" href="#movie/${m.id}?book=1">Đặt vé</a>`:`<button class="primary" onclick="remind(${m.id})">Theo dõi</button>`}<a class="outline" href="#movie/${m.id}">Chi tiết</a></div></div></article>`}
function renderFeed(){const status=$('#feedStatus')?.value||'now';const list=movies.filter(m=>(status==='all'||m.status===status)&&(filterGenre==='Tất cả'||m.genre===filterGenre));$('#homeGrid').innerHTML=list.length?list.map(miniMovieCard).join(''):'<div class="empty" style="grid-column:1/-1">Chưa có phim thuộc mục này. Hãy đổi thể loại hoặc trạng thái.</div>';if($('#feedCount'))$('#feedCount').textContent=list.length+' phim';$('#homeGenres').innerHTML=genreChips('homeFilter')}
function homeFilter(g){filterGenre=g;renderFeed()}
function movieList(params){movieStatus=params.get('status')==='soon'?'soon':'now';app.innerHTML=`<div class="container"><div class="eyebrow">KHÁM PHÁ ĐIỆN ẢNH</div><h1 class="page-title">Tìm bộ phim của bạn</h1><p class="sub">Những câu chuyện mới, những trải nghiệm đáng nhớ.</p><div class="chips"><button class="chip ${movieStatus==='now'?'active':''}" onclick="location.hash='movies?status=now'">Đang chiếu</button><button class="chip ${movieStatus==='soon'?'active':''}" onclick="location.hash='movies?status=soon'">Sắp chiếu</button></div><div class="filters"><label>Tìm theo tên phim<input id="movieQuery" placeholder="Nhập tên phim…" oninput="filterMovies()"></label><label>Thể loại<select id="genreSelect" onchange="filterMovies()"><option>Tất cả</option><option>Hành động</option><option>Tâm lý</option><option>Hoạt hình</option><option>Kinh dị</option></select></label><label>Sắp xếp<select id="sortSelect" onchange="filterMovies()"><option value="default">Nổi bật</option><option value="name">Tên A → Z</option><option value="duration">Thời lượng tăng dần</option></select></label></div><p class="result-count" id="resultCount"></p><div class="grid" id="movieGrid"></div></div>`;filterMovies()}
const normalize=s=>s.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/đ/g,'d');
function filterMovies(){const q=normalize($('#movieQuery').value),g=$('#genreSelect').value;let list=movies.filter(m=>m.status===movieStatus&&normalize(m.title).includes(q)&&(g==='Tất cả'||m.genre===g));const sort=$('#sortSelect').value;if(sort==='name')list.sort((a,b)=>a.title.localeCompare(b.title,'vi'));if(sort==='duration')list.sort((a,b)=>a.duration-b.duration);$('#resultCount').textContent=`${list.length} phim phù hợp`;$('#movieGrid').innerHTML=list.length?list.map(mCard).join(''):'<div class="empty" style="grid-column:1/-1">Không tìm thấy phim phù hợp. Hãy thử từ khóa khác.</div>'}
function trailer(id){const m=movies[id];showModal(`<div class="eyebrow">TRAILER MINH HỌA</div><h2 style="margin-top:12px">${esc(m.title)}</h2><video controls playsinline poster="assets/poster${id}.webp" style="width:100%;max-height:300px;margin:15px 0;background:black" src="https://interactive-examples.mdn.mozilla.net/media/cc0-videos/flower.mp4"></video><p class="notice">Video mẫu để thử trình phát, không phải trailer chính thức của phim. Khi tích hợp dữ liệu thật, thay bằng trailer được cấp phép.</p>`)}
function detail(id,params){
 const m=movies[id];if(!m)return notFound();
 const saved=(user()?.reminders||[]).includes(id);
 app.innerHTML=`<div class="film-detail-page"><div class="film-breadcrumb"><a href="#movies">← Khám phá phim</a><span>YeuMinhEm CINEMA / ${m.status==='now'?'ĐANG CHIẾU':'SẮP CHIẾU'}</span></div><section class="film-stage" style="--film-bg:url('assets/${id===0?'hero.webp':`poster${id}.webp`}')" aria-label="Thông tin ${esc(m.title)}"><div class="film-ambient"></div><aside class="film-rail"><a href="#movies" class="rail-menu" aria-label="Danh sách phim">☰</a><div class="rail-line"></div><div class="rail-dots">${movies.slice(0,5).map(x=>`<a href="#movie/${x.id}" class="${id===x.id?'selected':''}" aria-label="Xem ${esc(x.title)}"></a>`).join('')}</div><span class="rail-caption">ĐIỆN ẢNH</span></aside><div class="film-editorial"><div class="film-kicker">MỖI BỘ PHIM<br>MỘT THẾ GIỚI MỚI</div><h1 style="${m.title.length<24?'max-width:8ch':''}">${esc(m.title)}</h1><div class="film-short-meta"><span class="age">${m.age}</span><span>${m.genre}</span><span>${m.duration} phút</span></div><div class="actions film-main-actions">${m.status==='now'?`<button class="primary" onclick="jumpToTimes()">▰ Đặt vé ngay</button>`:`<button class="primary" onclick="remind(${id})">♡ Nhận thông báo</button>`}<button class="outline" onclick="trailer(${id})">▷ Trailer</button></div><p class="film-bottom-note">YeuMinhEm CINEMA · CHẠM VÀO ĐIỆN ẢNH</p></div><div class="film-art-card"><img src="assets/poster${id}.webp" alt="Poster ${esc(m.title)}" class="film-art"><div class="film-art-shade"></div><div class="film-art-heading"><div class="film-art-top"><h2>${esc(m.title.toUpperCase())}</h2><span class="film-more">•••</span></div><div class="film-art-meta">${m.status==='now'?'Đang chiếu':`Khởi chiếu ${m.release}`} <span class="rating">${m.age}</span> ${m.duration} phút · ${m.genre}</div><p>${esc(m.desc)}</p></div><div class="film-art-actions"><button class="primary" onclick="trailer(${id})">▶ Xem trailer</button><button id="saveFilm" class="round-action ${saved?'saved':''}" onclick="toggleWatch(${id})" aria-label="${saved?'Bỏ lưu phim':'Lưu phim'}" aria-pressed="${saved}">${saved?'♥':'♡'}</button><button class="round-action film-next" onclick="location.hash='movie/${(id+1)%movies.length}'" aria-label="Phim tiếp theo">↗</button></div></div></section><section class="film-story"><div><div class="eyebrow">CÂU CHUYỆN TRÊN MÀN ẢNH</div><h2>Nội dung phim</h2><p>${esc(m.desc)}</p></div><dl><div><dt>Đạo diễn</dt><dd>${esc(m.director||'Đang cập nhật')}</dd></div><div><dt>Diễn viên</dt><dd>${esc(m.cast||'Đang cập nhật')}</dd></div><div><dt>Ngôn ngữ</dt><dd>Tiếng Việt / Phụ đề Tiếng Việt</dd></div><div><dt>Định dạng</dt><dd>2D · ${m.age}</dd></div></dl></section>${m.status==='now'?`<section class="film-showtimes" id="showtimes"><div class="section-head"><div><div class="eyebrow">HẸN BẠN TẠI RẠP</div><h2>Chọn suất chiếu</h2></div><span class="sub">Từ 75.000 ₫ / vé</span></div>${scheduleControls(id)}<div id="showtimeList"></div></section>`:`<section class="film-showtimes"><div class="eyebrow">SẮP RA MẮT</div><h2>Hẹn bạn ngày ${m.release}</h2><p class="sub">Lịch chiếu sẽ được cập nhật khi phim mở bán.</p><button class="primary" onclick="remind(${id})">♡ Theo dõi phim</button></section>`}<section class="section"><div class="section-head"><h2>Có thể bạn cũng thích</h2><a href="#movies">Khám phá thêm ↗</a></div><div class="grid">${movies.filter(x=>x.id!==id&&x.status===m.status).slice(0,5).map(mCard).join('')}</div></section></div>`;
 if(m.status==='now'){renderTimes(id);if(params.get('book'))setTimeout(jumpToTimes,100)}
}
function jumpToTimes(){document.getElementById('showtimes')?.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth',block:'start'})}
function toggleWatch(id){if(!user()){loginNext=()=>toggleWatch(id);auth();return}const u=user();u.reminders=u.reminders||[];const has=u.reminders.includes(id);u.reminders=has?u.reminders.filter(x=>x!==id):[...u.reminders,id];store();const el=$('#saveFilm');if(el){el.textContent=has?'♡':'♥';el.classList.toggle('saved',!has);el.setAttribute('aria-pressed',String(!has));el.setAttribute('aria-label',has?'Lưu phim':'Bỏ lưu phim')}toast(has?'Đã bỏ lưu phim':'Đã lưu phim vào tài khoản')}
function scheduleControls(id,params=new URLSearchParams()){return `<div class="filters" style="grid-template-columns:1fr 1fr"><label>Chọn rạp<select id="schedCinema" onchange="renderTimes(${id})"><option value="all">Tất cả rạp</option>${cinemas.map(c=>`<option value="${c.id}" ${params.get('cinema')===String(c.id)?'selected':''}>${c.name}</option>`).join('')}</select></label><label>Ngày xem<select id="schedDate" onchange="renderTimes(${id})">${dayOptions()}</select></label></div>`}
function schedule(params){const requested=Number(params.get('movie')||0);const id=movies[requested]?.status==='now'?requested:0;app.innerHTML=`<div class="container"><div class="eyebrow">LÊN LỊCH HẸN VỚI ĐIỆN ẢNH</div><h1 class="page-title">Lịch chiếu</h1><label>Phim<select id="schedMovie" onchange="scheduleMovieChange()">${movies.filter(m=>m.status==='now').map(m=>`<option value="${m.id}" ${m.id===id?'selected':''}>${m.title}</option>`).join('')}</select></label>${scheduleControls(id,params)}<div id="showtimeList"></div></div>`;if([...$('#schedDate').options].some(o=>o.value===params.get('date')))$('#schedDate').value=params.get('date');renderTimes(id)}
function scheduleMovieChange(){const id=Number($('#schedMovie').value);$('#schedCinema').onchange=()=>renderTimes(id);$('#schedDate').onchange=()=>renderTimes(id);renderTimes(id)}
function renderTimes(id){const c=$('#schedCinema').value,date=$('#schedDate').value;$('#showtimeList').innerHTML=cinemas.filter(x=>c==='all'||x.id===Number(c)).map(x=>`<div class="cinema"><h3>${x.name}</h3><p>${x.address} · Phòng 01 · 2D phụ đề</p><div>${slots.map(t=>`<button class="showtime" ${validSlot(date,t)?'':'disabled'} onclick="startBooking(${id},${x.id},'${date}','${t}')">${t}</button>`).join('')}</div><p>Từ 75.000 ₫ / vé · Các suất đã qua giờ được khóa.</p></div>`).join('')}
function cinemaPage(){app.innerHTML=`<div class="container"><div class="eyebrow">MỘT ĐIỂM ĐẾN, NHIỀU TRẢI NGHIỆM</div><h1 class="page-title">Hệ thống rạp</h1><p class="sub">Danh sách địa điểm minh họa cho bản chạy thử.</p><label>Thành phố<select id="city" onchange="renderCinemas()"><option>Tất cả</option><option>TP. Hồ Chí Minh</option><option>Hà Nội</option></select></label><div id="cinemaList"></div></div>`;renderCinemas()}
function renderCinemas(){$('#cinemaList').innerHTML=cinemas.filter(c=>$('#city').value==='Tất cả'||c.city===$('#city').value).map(c=>`<div class="panel"><div class="eyebrow">2D · ÂM THANH VÒM · GHẾ VIP</div><h2>${c.name}</h2><p class="sub">${c.address}</p><p class="sub">Giờ hoạt động minh họa: 08:00 – 23:30</p><div class="actions"><a class="primary" href="#schedule?cinema=${c.id}">Xem lịch chiếu</a><button class="outline" onclick="info('Thông tin rạp','${c.name}: phòng chiếu 2D, ghế thường và ghế VIP. Địa điểm trong bản demo chỉ dùng để minh họa quy trình đặt vé.')">Thông tin rạp</button></div></div>`).join('')}
function account(){if(user()){location.hash='profile';return}auth('login')}
function auth(mode='login'){showModal(`<div class="eyebrow">YeuMinhEm CINEMA</div><h2 style="margin-top:15px">${mode==='register'?'Tạo tài khoản':'Chào mừng trở lại'}</h2><p class="sub">${mode==='register'?'Bắt đầu hành trình điện ảnh của bạn.':'Đăng nhập để đặt vé và xem lịch sử.'}</p><form id="authForm">${mode==='register'?'<label>Họ và tên<input name="name" required maxlength="70" placeholder="Tên của bạn" autocomplete="name"></label>':''}<label>Email<input name="email" type="email" required placeholder="ban@example.com" autocomplete="email"></label><label>Mã truy cập demo<input name="password" type="password" required minlength="6" placeholder="Tối thiểu 6 ký tự" autocomplete="off"></label><div class="error" id="authError"></div><button class="primary" type="submit">${mode==='register'?'Đăng ký':'Đăng nhập'}</button></form><button class="link" onclick="auth('${mode==='register'?'login':'register'}')">${mode==='register'?'Đã có tài khoản? Đăng nhập':'Chưa có tài khoản? Đăng ký'}</button><button class="outline" style="width:100%;margin:8px 0 18px" onclick="demoLogin()">Dùng tài khoản trải nghiệm</button><p class="notice">Tài khoản chỉ dùng thử trên trình duyệt này. Không sử dụng mật khẩu thật hoặc thông tin nhạy cảm.</p>`);$('#authForm').onsubmit=e=>submitAuth(e,mode)}
async function digest(t){if(crypto.subtle){const b=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(t));return [...new Uint8Array(b)].map(x=>x.toString(16).padStart(2,'0')).join('')}return btoa(unescape(encodeURIComponent(t)))}
async function submitAuth(e,mode){e.preventDefault();const f=new FormData(e.target),email=f.get('email').trim().toLowerCase(),password=await digest(f.get('password'));let u=users.find(x=>x.email===email);if(mode==='register'){if(u){$('#authError').textContent='Email này đã được đăng ký.';return}const name=f.get('name').trim();if(name.length<2){$('#authError').textContent='Tên cần ít nhất 2 ký tự.';return}u={id:uid(),name,email,password,phone:''};users.push(u)}else if(!u||u.password!==password){$('#authError').textContent='Email hoặc mã truy cập chưa đúng.';return}session=u.id;store();afterLogin()}
function demoLogin(){let u=users.find(x=>x.email==='guest@cinema.example');if(!u){u={id:uid(),name:'Khách trải nghiệm',email:'guest@cinema.example',phone:'',password:null};users.push(u)}session=u.id;store();afterLogin()}
function afterLogin(){closeModal();updateAccount();toast('Đăng nhập thành công');if(loginNext){const next=loginNext;loginNext=null;next()}else route()}
function remind(id){if(!movies[id])return;if(!user()){loginNext=()=>remind(id);auth();return}const u=user();u.reminders=u.reminders||[];if(!u.reminders.includes(id))u.reminders.push(id);store();toast('Đã lưu phim vào danh sách theo dõi của bạn')}
function startBooking(mid,cid,date,time){if(!movies[mid]||movies[mid].status!=='now'||!cinemas[cid]||!slots.includes(time)||!Array.from({length:7},(_,i)=>dateKey(i)).includes(date)){toast('Thông tin suất chiếu không hợp lệ. Vui lòng chọn lại.');location.hash='schedule';return}if(!validSlot(date,time)){toast('Suất chiếu này đã qua giờ. Vui lòng chọn suất khác.');return}if(!user()){loginNext=()=>startBooking(mid,cid,date,time);auth();return}if(booking?.orderId){toast('Bạn đang có đơn chờ xác nhận trong Vé của tôi.')}booking={mid,cid,date,time,seats:[],expires:Date.now()+300000,owner:session};persistBooking();location.hash='booking';if(location.hash==='#booking')bookingPage()}
function showKey(b){return [b.mid,b.cid,b.date,b.time].join('|')}
function expireOrders(){let dirty=false;orders.forEach(o=>{if(o.status==='pending'&&o.expires<=Date.now()){o.status='expired';dirty=true}});if(dirty){store();const path=location.hash.slice(1);if(path==='orders')ordersPage();else if(path.startsWith('checkout/')){const id=path.split('/')[1];if(getOrder(id)?.status==='expired'){toast('Đơn đã hết hạn, ghế đã được giải phóng.');checkoutPage(id)}}}}
function takenSeats(b){expireOrders();const key=showKey(b);const sold=orders.filter(o=>showKey(o)===key&&['paid','pending'].includes(o.status)&&o.id!==b.orderId).flatMap(o=>o.seats);const preset=['A3','B7','C4','D8','F2','G9'];return new Set([...preset,...sold])}
function seatPrice(s){return ['D','E','F'].includes(s[0])?95000:75000}
function sumSeats(b){return b.seats.reduce((s,x)=>s+seatPrice(x),0)}
function bookingPage(){if(!booking||booking.owner!==session){app.innerHTML='<div class="container"><h1>Chọn suất chiếu trước</h1><p class="sub">Bạn chưa có lượt chọn ghế đang diễn ra.</p><a class="primary" href="#schedule">Xem lịch chiếu</a></div>';return}const b=booking,m=movies[b.mid];if(!m||!cinemas[b.cid]){booking=null;persistBooking();return notFound()}if(b.orderId){const linked=getOrder(b.orderId);if(linked?.status==='pending'){location.hash='checkout/'+b.orderId;return}if(linked?.status==='paid'){location.hash='ticket/'+b.orderId;return}booking=null;persistBooking();location.hash='schedule';return}if(Date.now()>=b.expires){booking=null;persistBooking();toast('Đã hết thời gian chọn ghế. Vui lòng chọn lại.');location.hash='schedule';return}const taken=takenSeats(b);app.innerHTML=`<div class="container"><div class="steps"><span class="active">01 · Chọn ghế</span><span>02 · Xác nhận</span><span>03 · Nhận vé</span></div><h1 class="page-title">Chọn vị trí của bạn</h1><p class="sub">Tối đa 8 ghế mỗi đơn · Ghế VIP ở hàng D, E, F.</p><div class="booking"><div><div class="screen">MÀN HÌNH</div><div class="seatmap">${'ABCDEFGH'.split('').map(r=>`<div class="seatrow"><span class="rowlabel">${r}</span>${Array.from({length:10},(_,i)=>{const s=r+(i+1);return `<button class="seat ${['D','E','F'].includes(r)?'vip':''} ${b.seats.includes(s)?'selected':''}" ${taken.has(s)?'disabled':''} aria-label="Ghế ${s}${taken.has(s)?' đã đặt':''}" aria-pressed="${b.seats.includes(s)}" onclick="toggleSeat('${s}')">${s}</button>`}).join('')}<span class="rowlabel">${r}</span></div>`).join('')}</div><div class="legend"><span><i></i>Ghế trống</span><span><i class="chosen"></i>Đang chọn</span><span><i class="taken"></i>Đã đặt</span></div><p class="sub" style="text-align:center;font-size:11px">Ghế thường 75.000 ₫ · Ghế VIP 95.000 ₫</p></div><aside class="panel summary"><img src="assets/poster${m.id}.webp" alt=""><h3>${esc(m.title)}</h3><span class="age">${m.age}</span><p class="timer" id="countdown"></p><hr><div class="kv"><span>Rạp</span><b>${cinemas[b.cid].name}</b></div><div class="kv"><span>Suất chiếu</span><b>${b.time} · ${fmtDate(b.date)}</b></div><div class="kv"><span>Phòng</span><b>01 · 2D</b></div><div class="kv"><span>Ghế</span><b id="selectedSeats">${b.seats.join(', ')||'Chưa chọn'}</b></div><hr><div class="kv"><span>Tổng cộng</span><strong class="total" id="seatTotal">${money(sumSeats(b))}</strong></div><button class="primary" id="continueBtn" ${b.seats.length?'':'disabled'} onclick="checkout()">Tiếp tục →</button><a class="link" href="#movie/${m.id}">← Đổi suất chiếu</a></aside></div></div>`;updateTimer()}
function toggleSeat(s){if(!booking)return;if(booking.seats.includes(s))booking.seats=booking.seats.filter(x=>x!==s);else{if(booking.seats.length>=8){toast('Mỗi đơn chọn tối đa 8 ghế.');return}if(takenSeats(booking).has(s)){toast('Ghế vừa được đặt, vui lòng chọn ghế khác.');return}booking.seats.push(s)}persistBooking();bookingPage()}
function updateTimer(){if(!booking)return;const sec=Math.max(0,Math.floor((booking.expires-Date.now())/1000));if($('#countdown'))$('#countdown').textContent=`Thời gian còn lại: ${Math.floor(sec/60)}:${String(sec%60).padStart(2,'0')}`;if(sec<=0&&location.hash==='#booking'){booking=null;persistBooking();route();toast('Đã hết thời gian chọn ghế.')}}
setInterval(()=>{updateTimer();expireOrders()},1000);
function checkout(){const b=booking;if(!b||!b.seats.length)return;if(b.orderId&&getOrder(b.orderId)?.status==='pending'){location.hash='checkout/'+b.orderId;return;}if(b.expires<=Date.now()){booking=null;route();return}if(b.seats.some(s=>takenSeats(b).has(s))){toast('Có ghế vừa được đặt. Vui lòng chọn lại.');bookingPage();return}const o={...b,id:uid(),code:'CC'+Date.now().toString(36).toUpperCase().slice(-7),userId:session,status:'pending',created:Date.now(),amount:sumSeats(b)};orders.push(o);booking.orderId=o.id;store();location.hash='checkout/'+o.id}
function getOrder(id){return orders.find(o=>o.id===id&&o.userId===session)}
function checkoutPage(id){expireOrders();const o=getOrder(id);if(!o)return locked();if(o.status==='paid'){location.hash='ticket/'+id;return}if(o.status!=='pending'){app.innerHTML=`<div class="container"><h1>Đơn ${o.status==='expired'?'đã hết hạn':'đã hủy'}</h1><p class="sub">Ghế đã được giải phóng. Bạn có thể đặt một suất chiếu mới.</p><a class="primary" href="#schedule">Đặt vé mới</a></div>`;return}const m=movies[o.mid];app.innerHTML=`<div class="container" style="max-width:900px"><div class="steps"><span>01 · Chọn ghế</span><span class="active">02 · Xác nhận</span><span>03 · Nhận vé</span></div><h1 class="page-title">Xác nhận đặt vé</h1><div class="panel"><h2>${esc(m.title)}</h2><div class="kv"><span>Rạp chiếu</span><b>${cinemas[o.cid].name}</b></div><div class="kv"><span>Ngày và giờ</span><b>${fmtDate(o.date)} · ${o.time}</b></div><div class="kv"><span>Ghế ngồi</span><b>${o.seats.join(', ')}</b></div><div class="kv"><span>Mã đơn</span><b>${o.code}</b></div><div class="kv"><span>Hạn xác nhận</span><b>${new Date(o.expires).toLocaleTimeString('vi-VN')}</b></div><hr style="border:0;border-top:1px solid var(--line)"><div class="kv"><span>Tổng thanh toán mô phỏng</span><strong class="total">${money(o.amount)}</strong></div></div><form id="payForm"><h3>Thông tin nhận vé</h3><div class="form-row"><label>Họ tên<input required id="payName" value="${esc(user().name)}" maxlength="70"></label><label>Email<input required type="email" id="payEmail" value="${esc(user().email)}"></label></div><h3>Phương thức xác nhận</h3><label class="radio-option"><input type="radio" checked name="method"><div>Thanh toán mô phỏng<small>Không trừ tiền, không yêu cầu thông tin ngân hàng</small></div></label><p class="notice">Đây là giao dịch thử nghiệm. Sau xác nhận, ghế được đánh dấu đã đặt trong dữ liệu của trình duyệt này.</p><label style="display:flex;gap:10px;align-items:center;margin:20px 0"><input required type="checkbox" style="width:auto;margin:0">Tôi đã kiểm tra phim, suất chiếu và ghế.</label><div class="actions"><button class="primary" type="submit">Xác nhận đặt vé · ${money(o.amount)}</button><button type="button" class="outline" onclick="cancelOrder('${id}')">Hủy đơn</button></div></form></div>`;$('#payForm').onsubmit=e=>{e.preventDefault();confirmPayment(id)}}
function confirmPayment(id){expireOrders();const o=getOrder(id);if(!o||o.status!=='pending'){toast('Đơn không còn hiệu lực.');route();return}const conflicts=orders.some(x=>x.id!==id&&showKey(x)===showKey(o)&&['paid','pending'].includes(x.status)&&x.seats.some(s=>o.seats.includes(s)));if(conflicts){o.status='cancelled';store();toast('Ghế không còn trống. Vui lòng đặt lại.');location.hash='orders';return}o.status='paid';o.paid=Date.now();o.name=$('#payName').value.trim();o.email=$('#payEmail').value.trim();o.ticketStatus='unused';booking=null;store();location.hash='ticket/'+id;toast('Đặt vé thành công!')}
function cancelOrder(id){const o=getOrder(id);if(!o||o.status!=='pending')return;showModal(`<h2>Hủy đơn đặt vé?</h2><p class="sub">Đơn ${o.code} và các ghế ${o.seats.join(', ')} sẽ được giải phóng.</p><button class="primary" onclick="doCancel('${id}')">Xác nhận hủy đơn</button><button class="link" onclick="closeModal()">Giữ lại đơn</button>`)}
function doCancel(id){const o=getOrder(id);if(o?.status==='pending'){o.status='cancelled';if(booking?.orderId===id)booking=null;store()}closeModal();toast('Đã hủy đơn và giải phóng ghế');location.hash='orders';route()}
function ordersPage(){if(!user())return locked();expireOrders();app.innerHTML=`<div class="container"><div class="eyebrow">HÀNH TRÌNH ĐIỆN ẢNH CỦA BẠN</div><h1 class="page-title">Vé của tôi</h1><div class="chips" id="orderTabs">${['all','paid','pending','cancelled'].map((s,i)=>`<button class="chip ${i===0?'active':''}" onclick="renderOrders('${s}',this)">${{all:'Tất cả',paid:'Đã xác nhận',pending:'Chờ xác nhận',cancelled:'Đã hủy / hết hạn'}[s]}</button>`).join('')}</div><div id="orderList"></div></div>`;renderOrders('all')}
function renderOrders(status,el){if(el){$('#orderTabs').querySelectorAll('button').forEach(x=>x.classList.remove('active'));el.classList.add('active')}const list=orders.filter(o=>o.userId===session&&(status==='all'||(status==='cancelled'?['cancelled','expired'].includes(o.status):o.status===status))).sort((a,b)=>b.created-a.created);$('#orderList').innerHTML=list.length?list.map(o=>`<article class="ticket"><img src="assets/poster${o.mid}.webp" alt=""><div><h3>${esc(movies[o.mid].title)}</h3><span class="status">${statusText(o.status)}</span><p>${cinemas[o.cid].name}<br>${fmtDate(o.date)} · ${o.time} · Ghế ${o.seats.join(', ')}<br>${o.code} · ${money(o.amount)}</p></div><div>${o.status==='paid'?`<a class="primary" href="#ticket/${o.id}">Xem vé</a>`:o.status==='pending'?`<a class="primary" href="#checkout/${o.id}">Xác nhận</a><button class="link" onclick="cancelOrder('${o.id}')">Hủy đơn</button>`:`<a class="outline" href="#movie/${o.mid}?book=1">Đặt lại</a>`}</div></article>`).join(''):'<div class="empty">Chưa có đơn nào trong mục này.<br><br><a class="primary" href="#movies">Khám phá phim</a></div>'}
function statusText(s){return {paid:'Đã xác nhận',pending:'Chờ xác nhận',cancelled:'Đã hủy',expired:'Đã hết hạn'}[s]}
function ticketPage(id){const o=getOrder(id);if(!o||o.status!=='paid')return locked();app.innerHTML=`<div class="container success" style="max-width:650px"><div class="check">✓</div><div class="eyebrow">SẴN SÀNG CHO MỘT TRẢI NGHIỆM MỚI</div><h1>Vé của bạn đã sẵn sàng</h1><p class="sub">Lưu mã vé và xuất trình khi đến rạp.</p><div class="receipt"><h2>${esc(movies[o.mid].title)}</h2><div class="kv"><span>Rạp / Phòng</span><b>${cinemas[o.cid].name} / 01</b></div><div class="kv"><span>Ngày chiếu</span><b>${fmtDate(o.date)} · ${o.time}</b></div><div class="kv"><span>Ghế</span><b>${o.seats.join(', ')}</b></div><div class="kv"><span>Khách hàng</span><b>${esc(o.name||user().name)}</b></div><div class="kv"><span>Giá vé</span><b>${money(o.amount)}</b></div><div class="code">${o.code}</div><p style="text-align:center;font-size:11px;color:#586d80">VÉ MINH HỌA · KHÔNG CÓ GIÁ TRỊ SỬ DỤNG THỰC TẾ</p></div><div class="actions" style="justify-content:center"><button class="primary" onclick="downloadTicket('${o.id}')">↓ Tải thông tin vé</button><button class="outline" onclick="window.print()">In vé / Lưu PDF</button><a class="outline" href="#orders">Vé của tôi</a></div></div>`}
function downloadTicket(id){const o=getOrder(id);if(!o)return;const text=`YeuMinhEm CINEMA — VÉ MINH HỌA\nMã vé: ${o.code}\nPhim: ${movies[o.mid].title}\nRạp: ${cinemas[o.cid].name}\nNgày: ${fmtDate(o.date)} — ${o.time}\nGhế: ${o.seats.join(', ')}\nTổng: ${money(o.amount)}\nKhách hàng: ${o.name}\nKhông có giá trị sử dụng thực tế.`;const url=URL.createObjectURL(new Blob(['\uFEFF'+text],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=o.code+'.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function profilePage(){if(!user())return locked();const u=user();app.innerHTML=`<div class="container profile"><div class="eyebrow">TÀI KHOẢN CỦA BẠN</div><h1 class="page-title">Thông tin cá nhân</h1><form id="profileForm"><label>Họ và tên<input name="name" value="${esc(u.name)}" required minlength="2" maxlength="70"></label><label>Email<input value="${esc(u.email)}" disabled></label><label>Số điện thoại<input name="phone" type="tel" pattern="[0-9+ ()-]{8,18}" value="${esc(u.phone)}" placeholder="Chưa cập nhật"></label><button class="primary">Lưu thay đổi</button></form><div class="panel"><h3>Phim đang theo dõi</h3>${(u.reminders||[]).length?u.reminders.map(id=>`<p><a href="#movie/${id}">${esc(movies[id].title)} ↗</a><button class="link" onclick="removeReminder(${id})"> · Bỏ theo dõi</button></p>`).join(''):'<p class="sub">Chưa theo dõi phim nào. Bạn có thể theo dõi phim sắp chiếu ở trang chi tiết.</p>'}</div><div class="actions"><button class="outline" onclick="changePassword()">Đổi mã truy cập demo</button><button class="outline" onclick="logout()">Đăng xuất</button></div><p class="notice">Thông tin thử nghiệm chỉ lưu trên trình duyệt này. Xóa dữ liệu trình duyệt sẽ xóa tài khoản và lịch sử.</p></div>`;$('#profileForm').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);if(f.get('name').trim().length<2)return toast('Tên cần ít nhất 2 ký tự.');u.name=f.get('name').trim();u.phone=f.get('phone').trim();store();updateAccount();toast('Đã cập nhật thông tin')}}
function removeReminder(id){user().reminders=user().reminders.filter(x=>x!==id);store();profilePage()}
function changePassword(){if(user().password===null){info('Tài khoản trải nghiệm','Tài khoản trải nghiệm không có mã truy cập. Hãy đăng ký tài khoản demo riêng để thử chức năng này.');return}showModal('<h2>Đổi mã truy cập demo</h2><form id="passwordForm"><label>Mã hiện tại<input name="old" type="password" required></label><label>Mã mới<input name="next" type="password" required minlength="6"></label><label>Nhập lại mã mới<input name="confirm" type="password" required minlength="6"></label><div class="error" id="pwError"></div><button class="primary">Cập nhật</button></form>');$('#passwordForm').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target);if(await digest(f.get('old'))!==user().password){$('#pwError').textContent='Mã hiện tại chưa đúng.';return}if(f.get('next')!==f.get('confirm')){$('#pwError').textContent='Hai mã mới chưa khớp.';return}user().password=await digest(f.get('next'));store();closeModal();toast('Đã đổi mã truy cập demo')}}
function logout(){session=null;booking=null;loginNext=null;store();updateAccount();location.hash='home';toast('Đã đăng xuất')}
function locked(){app.innerHTML='<div class="container"><h1>Đăng nhập để tiếp tục</h1><p class="sub">Tài khoản giúp bạn quản lý vé và thông tin đặt chỗ.</p><button class="primary" onclick="account()">Đăng nhập / Đăng ký</button></div>'}
function openSearch(){showModal('<h2>Tìm kiếm phim</h2><input id="globalSearch" aria-label="Tên phim" placeholder="Nhập tên phim…" oninput="searchGlobal()"><div id="globalResults" class="search-results"></div>');searchGlobal();$('#globalSearch').focus()}
function searchGlobal(){const q=normalize($('#globalSearch').value),list=movies.filter(m=>normalize(m.title).includes(q));$('#globalResults').innerHTML=list.length?list.map(m=>`<button class="search-result" onclick="closeModal();location.hash='movie/${m.id}'"><img src="assets/poster${m.id}.webp" alt=""><div>${esc(m.title)}<small>${m.genre} · ${m.duration} phút · ${m.status==='now'?'Đang chiếu':'Sắp chiếu'}</small></div></button>`).join(''):'<p class="sub">Không tìm thấy phim.</p>'}
function notFound(){app.innerHTML='<div class="container"><h1>Không tìm thấy trang</h1><a class="primary" href="#home">Về trang chủ</a></div>'}
function route(){clearInterval(slideTimer);closeMenu();const [path,query='']=(location.hash.slice(1)||'home').split('?'),parts=path.split('/'),params=new URLSearchParams(query);document.body.classList.toggle('home-view',parts[0]==='home');const activeRoute=({movie:'movies',booking:'schedule',checkout:'orders',ticket:'orders'})[parts[0]]||parts[0];document.querySelectorAll('nav a').forEach(a=>{const selected=a.hash==='#'+activeRoute;a.classList.toggle('active',selected);if(selected)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')});window.scrollTo(0,0);if($('#modal').open)closeModal();switch(parts[0]){case 'home':home();break;case 'movies':movieList(params);break;case 'movie':detail(Number(parts[1]),params);break;case 'schedule':schedule(params);break;case 'cinemas':cinemaPage();break;case 'booking':bookingPage();break;case 'checkout':checkoutPage(parts[1]);break;case 'orders':ordersPage();break;case 'ticket':ticketPage(parts[1]);break;case 'profile':profilePage();break;default:notFound()}updateAccount()}
document.addEventListener('keydown',e=>{if(document.querySelector('#hero')?.contains(document.activeElement)){if(e.key==='ArrowRight'){e.preventDefault();setSlide(slide+1)}if(e.key==='ArrowLeft'){e.preventDefault();setSlide(slide-1)}}});window.addEventListener('hashchange',route);window.addEventListener('storage',e=>{if(e.key==='cc_orders'){orders=read('cc_orders',[]);if(location.hash==='#booking'&&booking)bookingPage()}});route();
